import re, struct, zlib
from math import floor

path = '/app/text.gcode'
active = None
abs_xy = True
extruder_mode = 'relative'
current = {'X':0.0,'Y':0.0,'Z':0.0}
current_E = 0.0
segments = []
minx=miny=1e9
maxx=maxy=-1e9

line_re = re.compile(r'([XYZE])(-?\d+\.?\d*)')

with open(path,'r',errors='ignore') as f:
    for line in f:
        line=line.strip()
        if not line:
            continue
        if line.startswith('M486'):
            m = re.search(r'S(-?\d+)', line)
            if m:
                s = int(m.group(1))
                if s == -1:
                    active = None
                else:
                    active = s
            continue
        if line.startswith('G90'):
            abs_xy = True
            continue
        if line.startswith('G91'):
            abs_xy = False
            continue
        if line.startswith('M82'):
            extruder_mode = 'absolute'
            continue
        if line.startswith('M83'):
            extruder_mode = 'relative'
            continue
        if line.startswith('G92'):
            for axis,val in line_re.findall(line):
                v=float(val)
                if axis=='E':
                    current_E = v
                else:
                    current[axis]=v
            continue
        if line.startswith('G0') or line.startswith('G1'):
            tokens = line_re.findall(line)
            if not tokens:
                continue
            newX = current['X']
            newY = current['Y']
            newZ = current['Z']
            newE = None
            for axis,val in tokens:
                v=float(val)
                if axis=='X':
                    newX = v if abs_xy else current['X'] + v
                elif axis=='Y':
                    newY = v if abs_xy else current['Y'] + v
                elif axis=='Z':
                    newZ = v if abs_xy else current['Z'] + v
                elif axis=='E':
                    newE = v
            extrude = False
            if newE is not None:
                if extruder_mode=='relative':
                    if newE > 0:
                        extrude = True
                    current_E += newE
                else:
                    delta = newE - current_E
                    if delta > 0:
                        extrude = True
                    current_E = newE
            if extrude and active==0:
                if newX != current['X'] or newY != current['Y']:
                    segments.append((current['X'], current['Y'], newX, newY))
                    minx = min(minx, current['X'], newX)
                    maxx = max(maxx, current['X'], newX)
                    miny = min(miny, current['Y'], newY)
                    maxy = max(maxy, current['Y'], newY)
            current['X']=newX; current['Y']=newY; current['Z']=newZ

print('segments', len(segments))
print('bbox', minx, miny, maxx, maxy)

if not segments:
    raise SystemExit('no segments')

# rasterize
scale = 8  # pixels per mm
margin = 10
width = int((maxx - minx) * scale) + 2*margin + 1
height = int((maxy - miny) * scale) + 2*margin + 1
print('size', width, height)

# create image as list of bytearrays (white background 255)
rows = [bytearray([255])*width for _ in range(height)]

# draw line with simple Bresenham

def draw_point(x,y,th=1):
    # set a square of size (2*th+1)
    for dy in range(-th, th+1):
        yy = y+dy
        if 0 <= yy < height:
            row = rows[yy]
            for dx in range(-th, th+1):
                xx = x+dx
                if 0 <= xx < width:
                    row[xx] = 0


def draw_line(x0,y0,x1,y1,th=1):
    dx = abs(x1 - x0)
    dy = -abs(y1 - y0)
    sx = 1 if x0 < x1 else -1
    sy = 1 if y0 < y1 else -1
    err = dx + dy
    while True:
        draw_point(x0,y0,th)
        if x0 == x1 and y0 == y1:
            break
        e2 = 2*err
        if e2 >= dy:
            err += dy
            x0 += sx
        if e2 <= dx:
            err += dx
            y0 += sy

# draw segments
thickness = max(1, int(scale*0.4/2))  # approximate line thickness for 0.4mm nozzle
for (x1,y1,x2,y2) in segments:
    px1 = int((x1 - minx)*scale) + margin
    py1 = int((maxy - y1)*scale) + margin
    px2 = int((x2 - minx)*scale) + margin
    py2 = int((maxy - y2)*scale) + margin
    draw_line(px1, py1, px2, py2, th=thickness)

# write png
raw = b''.join(b'\x00'+bytes(r) for r in rows)
compressed = zlib.compress(raw, level=9)

def chunk(tag,data):
    return struct.pack('>I', len(data)) + tag + data + struct.pack('>I', zlib.crc32(tag+data) & 0xffffffff)

ihdr = struct.pack('>IIBBBBB', width, height, 8, 0, 0, 0, 0)

png = b'\x89PNG\r\n\x1a\n' + chunk(b'IHDR', ihdr) + chunk(b'IDAT', compressed) + chunk(b'IEND', b'')

with open('/app/text_render.png','wb') as out:
    out.write(png)

print('wrote /app/text_render.png')
